[
  {
    "question": "In the context of Indian higher secondary education, a \"dropper\" is best defined as:",
    "options": {
      "A": "A student who repeats class XI or XII to improve their board exam scores.",
      "B": "A student who switches from science to commerce after class X.",
      "C": "A student who enrolls in a vocational course instead of formal schooling.",
      "D": "A student who takes a gap year before joining a university."
    },
    "correct_answer": "A",
    "explanation": "A dropper specifically refers to a student who repeats a year (usually class XI or XII) to achieve higher marks, often to qualify for competitive exams like JEE.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following is the most common reason for students to become droppers after class X?",
    "options": {
      "A": "Desire to change their career path to arts.",
      "B": "Need to improve JEE Main/Advanced scores for engineering admissions.",
      "C": "Lack of interest in extracurricular activities.",
      "D": "Family relocation to a different state."
    },
    "correct_answer": "B",
    "explanation": "The primary driver for dropping a year in classes XI‑XII is to raise JEE scores, as engineering seats are highly competitive.",
    "difficulty": "Medium"
  },
  {
    "question": "According to recent trends, what is the approximate percentage of Class XII students who opt to repeat the year for JEE preparation?",
    "options": {
      "A": "5‑7 %",
      "B": "10‑12 %",
      "C": "15‑18 %",
      "D": "20‑25 %"
    },
    "correct_answer": "C",
    "explanation": "Surveys by coaching institutes show that about 15‑18 % of Class XII aspirants repeat the year to focus on JEE preparation.",
    "difficulty": "Medium"
  },
  {
    "question": "Which strategy is most effective for a dropper to avoid burnout during the repeated year?",
    "options": {
      "A": "Studying continuously for 10‑12 hours without breaks.",
      "B": "Following a balanced timetable with regular mock tests and leisure activities.",
      "C": "Skipping board exam preparation and focusing only on JEE.",
      "D": "Changing coaching centers every month."
    },
    "correct_answer": "B",
    "explanation": "A balanced schedule that includes mock tests, revision, and adequate rest helps maintain motivation and prevents burnout.",
    "difficulty": "Medium"
  },
  {
    "question": "When a student repeats class XI, which of the following subjects typically receives the highest weightage in JEE Main preparation?",
    "options": {
      "A": "Coordinate Geometry",
      "B": "Probability",
      "C": "Linear Algebra",
      "D": "Number Theory"
    },
    "correct_answer": "A",
    "explanation": "Coordinate Geometry, together with Integration, contributes about 20‑23 % of JEE marks, making it a priority for droppers.",
    "difficulty": "Medium"
  }
]
